import pythoncom
from win32com.client import constants

def safe_autocad_operation(operation_func, *args, **kwargs):
    """Execute AutoCAD operation with comprehensive error handling"""
    try:
        result = operation_func(*args, **kwargs)
        return True, result
    except pythoncom.com_error as e:
        error_code = e.hresult
        if error_code == -2147352567:
            return False, "Invalid parameter or method call"
        elif error_code == -2147467259:
            return False, "AutoCAD application not available"
        else:
            return False, f"COM Error {error_code}: {e}"
    except AttributeError as e:
        return False, f"Invalid object attribute: {e}"
    except Exception as e:
        return False, f"Unexpected error: {e}"

def create_entity_safely(model_space, entity_type, *params):
    """Create entity with error handling"""
    success, result = safe_autocad_operation(
        getattr(model_space, f'Add{entity_type}'), *params
    )

    if success:
        print(f"Successfully created {entity_type}")
        return result
    else:
        print(f"Failed to create {entity_type}: {result}")
        return None
